local vars = require("vars")
require("keybinds")

-- Catppuccin Latte palette
local latte = require("catppuccin-latte")

-- Helper: Catppuccin hex + alpha -> rgba(...)
local function rgba(hex, alpha)
    return string.format("rgba(%s%s)", hex, alpha)
end

-- AUTOGENERATED HYPRLAND CONFIG.                        --
-- EDIT THIS CONFIG ACCORDING TO THE WIKI INSTRUCTIONS.  --
hl.config({ autogenerated = false }) -- remove this line to remove the warning

---- MONITORS ----
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "1.2",
})

